"use client"

import { useState } from "react"
import { useRouter } from 'next/navigation'
import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { ChevronDown } from 'lucide-react'
import { useToast } from "@/hooks/use-toast"

const statusOptions = [
  { value: 'pending', label: 'En attente', color: 'text-yellow-600' },
  { value: 'confirmed', label: 'Confirmée', color: 'text-blue-600' },
  { value: 'shipped', label: 'Expédiée', color: 'text-purple-600' },
  { value: 'delivered', label: 'Livrée', color: 'text-green-600' },
  { value: 'cancelled', label: 'Annulée', color: 'text-red-600' },
]

export function UpdateOrderStatusButton({
  orderId,
  currentStatus,
  onStatusUpdated,
}: {
  orderId: string
  currentStatus: string
  onStatusUpdated?: () => void
}) {
  const { toast } = useToast()
  const [isUpdating, setIsUpdating] = useState(false)

  const handleUpdateStatus = async (newStatus: string) => {
    setIsUpdating(true)

    try {
      const response = await fetch('/api/admin/orders/status', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ orderId, status: newStatus }),
      })

      if (!response.ok) throw new Error('Failed to update status')

      toast({
        title: "Statut mis à jour",
        description: "Le statut de la commande a été modifié avec succès.",
      })

      if (onStatusUpdated) {
        onStatusUpdated()
      }
    } catch (error) {
      console.error("Update status error:", error)
      toast({
        title: "Erreur",
        description: "Impossible de mettre à jour le statut.",
        variant: "destructive",
      })
    } finally {
      setIsUpdating(false)
    }
  }

  const currentStatusLabel = statusOptions.find(
    (option) => option.value === currentStatus
  )?.label

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant="outline" size="sm" disabled={isUpdating}>
          {isUpdating ? "..." : (currentStatusLabel || currentStatus)}
          <ChevronDown className="ml-2 h-4 w-4" />
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end">
        {statusOptions.map((option) => (
          <DropdownMenuItem
            key={option.value}
            onClick={() => handleUpdateStatus(option.value)}
            disabled={option.value === currentStatus}
            className={option.color}
          >
            {option.label}
          </DropdownMenuItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

